/* One language of the UI dictionary, cut out of messages.ts at build time by
   scripts/i18n-locale-loader.cjs (QA H-02). */
declare module "*?locale=uz" {
  const table: Record<string, string>;
  export default table;
}
declare module "*?locale=ru" {
  const table: Record<string, string>;
  export default table;
}
declare module "*?locale=en" {
  const table: Record<string, string>;
  export default table;
}
